// Monta o texto do rascunho de resposta com a assinatura do dono: a imagem (um arquivo no OneDrive)
// e o e-mail logo abaixo. Sem a imagem no OneDrive, a assinatura sai só com o e-mail.
const pedido = $('Quando pedirem um rascunho de resposta').first().json;
const assinatura = $('Assinatura').first().json;
const info = $input.first().json;

const idEmail = String(pedido.id_email ?? '').trim();
const texto = String(pedido.texto ?? '').trim();
if (!idEmail) throw new Error('Faltou o id do e-mail a responder.');
if (!texto) throw new Error('Faltou o texto da resposta.');

const escapar = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Largura e altura lidas do cabeçalho da imagem (PNG, GIF ou JPG), para ela não aparecer gigante.
function medidas(buf) {
  if (buf.length >= 24 && buf.readUInt32BE(0) === 0x89504e47) return { largura: buf.readUInt32BE(16), altura: buf.readUInt32BE(20) };
  if (buf.length >= 10 && buf.toString('ascii', 0, 3) === 'GIF') return { largura: buf.readUInt16LE(6), altura: buf.readUInt16LE(8) };
  if (buf.length >= 4 && buf[0] === 0xff && buf[1] === 0xd8) {
    let i = 2;
    while (i + 9 < buf.length) {
      if (buf[i] !== 0xff) return { largura: 0, altura: 0 };
      const marca = buf[i + 1];
      if (marca === 0xff) {
        i++;
        continue;
      }
      if (marca >= 0xc0 && marca <= 0xcf && marca !== 0xc4 && marca !== 0xc8 && marca !== 0xcc) {
        return { altura: buf.readUInt16BE(i + 5), largura: buf.readUInt16BE(i + 7) };
      }
      i += 2 + buf.readUInt16BE(i + 2);
    }
  }
  return { largura: 0, altura: 0 };
}

const TIPOS = { 'image/png': 'png', 'image/jpeg': 'jpg', 'image/jpg': 'jpg', 'image/gif': 'gif' };
const CID = 'assinatura-kira';
let imagem = null;
let aviso = '';
const link = info['@microsoft.graph.downloadUrl'];
const tipo = String(info.file?.mimeType ?? '').toLowerCase();
if (!link) {
  aviso = `não achei a imagem da assinatura no OneDrive (${assinatura.imagem_onedrive}), então a assinatura saiu só com o e-mail`;
} else if (!TIPOS[tipo]) {
  aviso = 'a imagem da assinatura precisa ser PNG, JPG ou GIF, então a assinatura saiu só com o e-mail';
} else if (Number(info.size) > 1024 * 1024) {
  aviso = 'a imagem da assinatura passa de 1 MB, então a assinatura saiu só com o e-mail';
} else {
  try {
    const buf = Buffer.from(await this.helpers.httpRequest({ url: link, encoding: 'arraybuffer', timeout: 30000 }));
    const { largura, altura } = medidas(buf);
    const maxima = Number(assinatura.largura_maxima) || 600;
    const escala = largura > maxima ? maxima / largura : 1;
    imagem = {
      nome: `assinatura.${TIPOS[tipo]}`,
      tipo: tipo === 'image/jpg' ? 'image/jpeg' : tipo,
      base64: buf.toString('base64'),
      largura: Math.round(largura * escala),
      altura: Math.round(altura * escala),
    };
  } catch (erro) {
    aviso = `não consegui baixar a imagem da assinatura (${String(erro.message ?? erro).slice(0, 120)}), então a assinatura saiu só com o e-mail`;
  }
}

const email = String(assinatura.email ?? '').trim();
const partes = [];
if (imagem) {
  const tamanho = imagem.largura && imagem.altura ? ` width="${imagem.largura}" height="${imagem.altura}"` : '';
  partes.push(`<img src="cid:${CID}" alt="Assinatura"${tamanho} style="border:0">`);
}
if (email) partes.push(`<a href="mailto:${escapar(email)}">${escapar(email)}</a>`);
const comentario = escapar(texto).replace(/\r?\n/g, '<br>') + (partes.length ? '<br><br>' + partes.join('<br>') : '');

return [{ json: { id_email: idEmail, referencia: String(pedido.referencia ?? ''), comentario, cid: CID, imagem, aviso } }];

// Resposta final: o rascunho criado (id e link) e como a assinatura ficou.
const montado = $('Montar resposta').first().json;
const rascunho = $('Criar rascunho').first().json;
let assinatura = montado.imagem ? 'imagem e e-mail' : 'só o e-mail';
let aviso = montado.aviso || '';
if (montado.imagem) {
  const anexo = $input.first().json;
  if (!anexo.id || anexo.error) {
    assinatura = 'só o e-mail';
    aviso = 'não consegui colocar a imagem da assinatura no rascunho; confira antes de enviar';
  }
}
return [
  {
    json: {
      ok: true,
      id: rascunho.id,
      webLink: rascunho.webLink,
      isDraft: true,
      referencia: montado.referencia,
      assinatura,
      aviso,
      mensagem:
        `Rascunho criado na pasta Rascunhos do Outlook, com a assinatura (${assinatura}). Nada foi enviado: o dono revisa e envia.` +
        (aviso ? ` Atenção: ${aviso}.` : ''),
    },
  },
];

// Falha ao montar ou criar o rascunho: devolve o motivo em poucas palavras (a Kira explica ao dono;
// os rascunhos automáticos registram e avisam).
const falha = $input.first().json;
const erro = String(falha.error?.message ?? falha.error ?? 'erro desconhecido').slice(0, 300);
let referencia = '';
try {
  referencia = String($('Quando pedirem um rascunho de resposta').first().json.referencia ?? '');
} catch (e) {}
let orientacao = 'Não consegui criar o rascunho. Explique o erro ao dono em poucas palavras.';
if (/404|not ?found|ItemNotFound/i.test(erro)) {
  orientacao = 'Não achei esse e-mail no Outlook (o id pode estar errado ou o e-mail foi apagado). Busque o e-mail de novo e use o id que vier.';
} else if (/401|403|unauthori[sz]ed|forbidden|token/i.test(erro)) {
  orientacao = 'A conexão com o Outlook precisa ser refeita no n8n (credencial Microsoft Outlook). Explique isso ao dono.';
}
return [{ json: { ok: false, error: erro, referencia, orientacao } }];
